CREATE TABLE audiobook_daily_stats (
	id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	scope VARCHAR(32) NOT NULL, 
	reader_id INTEGER, 
	book_id INTEGER, 
	chapter_id INTEGER, 
	source VARCHAR(32) NOT NULL, 
	listened_ms BIGINT, 
	sessions INTEGER, 
	starts INTEGER, 
	completes INTEGER, 
	requests INTEGER, 
	bytes_sent BIGINT, 
	PRIMARY KEY (id)
);
CREATE TABLE author_aliases (
	normalized_name VARCHAR(500) NOT NULL, 
	name VARCHAR(500) NOT NULL, 
	canonical_name VARCHAR(500) NOT NULL, 
	canonical_normalized_name VARCHAR(500) NOT NULL, 
	PRIMARY KEY (normalized_name)
);
CREATE TABLE book_aliases (
	id INTEGER NOT NULL, 
	book_id INTEGER NOT NULL, 
	name VARCHAR(500) NOT NULL, 
	normalized_name VARCHAR(500) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_book_alias_name UNIQUE (book_id, normalized_name)
);
CREATE TABLE book_sources (
	id INTEGER NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	url VARCHAR(767) NOT NULL, 
	"group" VARCHAR(200), 
	source_type INTEGER, 
	enabled BOOLEAN, 
	weight INTEGER, 
	comment VARCHAR(500), 
	last_check_time DATETIME, 
	last_check_ok BOOLEAN, 
	check_status VARCHAR(20), 
	check_message VARCHAR(500), 
	check_tags TEXT, 
	create_time DATETIME, 
	update_time DATETIME, 
	raw TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE installed_themes (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	version VARCHAR(20), 
	author VARCHAR(100), 
	description VARCHAR(500), 
	active BOOLEAN, 
	installed_at DATETIME, 
	data TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE online_book_meta (
	book_id INTEGER NOT NULL, 
	source_url VARCHAR(1000), 
	origin_book_url VARCHAR(1000), 
	serialize_status VARCHAR(20) NOT NULL, 
	status_manual BOOLEAN, 
	last_chapter VARCHAR(300), 
	create_time DATETIME, 
	update_time DATETIME, 
	data TEXT, 
	PRIMARY KEY (book_id)
);
CREATE TABLE opds_sources (
	id INTEGER NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	url VARCHAR(1000) NOT NULL, 
	description VARCHAR(500), 
	active BOOLEAN, 
	create_time DATETIME, 
	update_time DATETIME, 
	data TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE plugin_definitions (
	id INTEGER NOT NULL, 
	plugin_key VARCHAR(200) NOT NULL, 
	version VARCHAR(64) NOT NULL, 
	protocol_version VARCHAR(64) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	runtime_kind VARCHAR(32) NOT NULL, 
	categories TEXT NOT NULL, 
	capabilities TEXT NOT NULL, 
	actions TEXT NOT NULL, 
	auth_schema TEXT, 
	config_schema TEXT, 
	permissions TEXT NOT NULL, 
	data_policy TEXT, 
	compatibility TEXT, 
	homepage VARCHAR(1000), 
	license VARCHAR(100), 
	manifest TEXT, 
	create_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_definition_key_version UNIQUE (plugin_key, version)
);
CREATE TABLE plugin_secrets (
	id INTEGER NOT NULL, 
	owner_type VARCHAR(32) NOT NULL, 
	owner_id INTEGER NOT NULL, 
	kind VARCHAR(64) NOT NULL, 
	ciphertext TEXT NOT NULL, 
	key_id VARCHAR(64) NOT NULL, 
	version INTEGER NOT NULL, 
	mask_hint VARCHAR(32), 
	create_time DATETIME NOT NULL, 
	last_rotated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE readers (
	id INTEGER NOT NULL, 
	username VARCHAR(200), 
	password VARCHAR(200), 
	salt VARCHAR(200), 
	name VARCHAR(100), 
	email VARCHAR(200), 
	avatar VARCHAR(200), 
	admin BOOLEAN, 
	active BOOLEAN, 
	permission VARCHAR(100), 
	create_time DATETIME, 
	update_time DATETIME, 
	access_time DATETIME, 
	extra TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE scanfiles (
	id INTEGER NOT NULL, 
	scan_id INTEGER, 
	import_id INTEGER, 
	name VARCHAR(512), 
	path VARCHAR(1024), 
	hash VARCHAR(512), 
	status VARCHAR(24), 
	title VARCHAR(100), 
	author VARCHAR(100), 
	publisher VARCHAR(100), 
	tags VARCHAR(100), 
	create_time DATETIME, 
	update_time DATETIME, 
	book_id INTEGER, 
	data TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (hash)
);
CREATE TABLE annotations (
	id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	book_id INTEGER NOT NULL, 
	client_id VARCHAR(64), 
	annotation_type VARCHAR(32) NOT NULL, 
	is_private BOOLEAN NOT NULL, 
	cfi TEXT, 
	chapter VARCHAR(500), 
	quote_text TEXT, 
	content TEXT, 
	color VARCHAR(32), 
	author_name VARCHAR(255), 
	user_modified_at DATETIME, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_annotation_client_id UNIQUE (reader_id, book_id, client_id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id) ON DELETE CASCADE
);
CREATE TABLE audiobook_editions (
	id INTEGER NOT NULL, 
	book_id INTEGER NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	engine VARCHAR(32) NOT NULL, 
	config TEXT, 
	source_fingerprint VARCHAR(64), 
	script_path VARCHAR(1024), 
	manifest_path VARCHAR(1024), 
	chapter_count INTEGER, 
	completed_count INTEGER, 
	duration_ms BIGINT, 
	size_bytes BIGINT, 
	created_by INTEGER NOT NULL, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	published_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(created_by) REFERENCES readers (id)
);
CREATE TABLE devices (
	id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	name VARCHAR(64) NOT NULL, 
	device_type VARCHAR(32) NOT NULL, 
	ip VARCHAR(128), 
	port INTEGER, 
	schema VARCHAR(8), 
	mailbox VARCHAR(256), 
	create_time DATETIME, 
	update_time DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id)
);
CREATE TABLE items (
	book_id INTEGER NOT NULL, 
	count_guest INTEGER NOT NULL, 
	count_visit INTEGER NOT NULL, 
	count_download INTEGER NOT NULL, 
	website VARCHAR(255) NOT NULL, 
	collector_id INTEGER, 
	scope VARCHAR(50) NOT NULL, 
	book_type VARCHAR(20) NOT NULL, 
	media_type VARCHAR(20) NOT NULL, 
	media_type_locked BOOLEAN NOT NULL, 
	create_time DATETIME, 
	src_path VARCHAR(4096) NOT NULL, 
	PRIMARY KEY (book_id), 
	FOREIGN KEY(collector_id) REFERENCES readers (id)
);
CREATE TABLE messages (
	id INTEGER NOT NULL, 
	title VARCHAR(200), 
	status VARCHAR(100), 
	unread BOOLEAN, 
	create_time DATETIME, 
	update_time DATETIME, 
	data TEXT, 
	reader_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id)
);
CREATE TABLE plugin_installations (
	id INTEGER NOT NULL, 
	plugin_key VARCHAR(200) NOT NULL, 
	definition_id INTEGER NOT NULL, 
	version VARCHAR(64) NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	scope VARCHAR(32) NOT NULL, 
	config TEXT, 
	installed_from VARCHAR(1000), 
	checksum VARCHAR(128), 
	status VARCHAR(32) NOT NULL, 
	installed_by INTEGER NOT NULL, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(definition_id) REFERENCES plugin_definitions (id), 
	FOREIGN KEY(installed_by) REFERENCES readers (id)
);
CREATE TABLE podcast_subscriptions (
	id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	token_hint VARCHAR(16), 
	active BOOLEAN NOT NULL, 
	hidden_books TEXT, 
	create_time DATETIME NOT NULL, 
	last_access_at DATETIME, 
	revoked_at DATETIME, 
	frozen_at DATETIME, 
	frozen_reason VARCHAR(500), 
	PRIMARY KEY (id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id)
);
CREATE TABLE reading_state (
	book_id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	favorite INTEGER, 
	favorite_date DATETIME, 
	wants INTEGER, 
	wants_date DATETIME, 
	read_state INTEGER NOT NULL, 
	read_date DATETIME, 
	online_read INTEGER, 
	download INTEGER, 
	progress TEXT, 
	progress_update_time DATETIME, 
	PRIMARY KEY (book_id, reader_id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id)
);
CREATE TABLE annotation_sources (
	id INTEGER NOT NULL, 
	annotation_id INTEGER NOT NULL, 
	source_name VARCHAR(64) NOT NULL, 
	source_connection_id VARCHAR(128) NOT NULL, 
	source_annotation_id VARCHAR(255), 
	source_run_id VARCHAR(128), 
	source_position TEXT, 
	source_raw_hash VARCHAR(128), 
	source_updated_at DATETIME, 
	source_sync_status VARCHAR(16) NOT NULL, 
	source_synced_at DATETIME, 
	source_sync_error TEXT, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_annotation_source_connection UNIQUE (annotation_id, source_name, source_connection_id), 
	CONSTRAINT uq_annotation_source_identity UNIQUE (source_name, source_connection_id, source_annotation_id), 
	FOREIGN KEY(annotation_id) REFERENCES annotations (id) ON DELETE CASCADE
);
CREATE TABLE audiobook_chapters (
	id INTEGER NOT NULL, 
	edition_id INTEGER NOT NULL, 
	source_key VARCHAR(1024), 
	number INTEGER NOT NULL, 
	title VARCHAR(512), 
	audio_path VARCHAR(1024), 
	timeline_path VARCHAR(1024), 
	duration_ms BIGINT, 
	size_bytes BIGINT, 
	content_hash VARCHAR(64), 
	episode_guid VARCHAR(128), 
	first_published_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_audiobook_chapter_number UNIQUE (edition_id, number), 
	FOREIGN KEY(edition_id) REFERENCES audiobook_editions (id)
);
CREATE TABLE audiobook_jobs (
	id INTEGER NOT NULL, 
	book_id INTEGER NOT NULL, 
	edition_id INTEGER NOT NULL, 
	creator_id INTEGER NOT NULL, 
	mode VARCHAR(24) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	phase VARCHAR(32), 
	priority INTEGER NOT NULL, 
	config TEXT, 
	chapter_selection VARCHAR(1024), 
	config_hash VARCHAR(64), 
	progress FLOAT, 
	lease_owner VARCHAR(128), 
	lease_until DATETIME, 
	last_event_seq BIGINT NOT NULL, 
	cancel_requested BOOLEAN, 
	cancel_requested_at DATETIME, 
	attempts INTEGER, 
	error_code VARCHAR(128), 
	error_message TEXT, 
	log_path VARCHAR(1024), 
	data TEXT, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	started_at DATETIME, 
	finished_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(edition_id) REFERENCES audiobook_editions (id), 
	FOREIGN KEY(creator_id) REFERENCES readers (id)
);
CREATE TABLE audiobook_playback_sessions (
	id INTEGER NOT NULL, 
	uuid VARCHAR(64) NOT NULL, 
	reader_id INTEGER NOT NULL, 
	edition_id INTEGER NOT NULL, 
	source VARCHAR(32), 
	device_id VARCHAR(128), 
	ip VARCHAR(128), 
	user_agent VARCHAR(1000), 
	started_at DATETIME NOT NULL, 
	ended_at DATETIME, 
	current_ms BIGINT, 
	listened_ms BIGINT, 
	completed BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id), 
	FOREIGN KEY(edition_id) REFERENCES audiobook_editions (id)
);
CREATE TABLE plugin_connections (
	id INTEGER NOT NULL, 
	installation_id INTEGER NOT NULL, 
	owner_type VARCHAR(32) NOT NULL, 
	owner_id INTEGER NOT NULL, 
	role VARCHAR(64) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	secret_id INTEGER, 
	config TEXT, 
	scopes TEXT NOT NULL, 
	schedule VARCHAR(128), 
	cursor TEXT, 
	health VARCHAR(32) NOT NULL, 
	health_message VARCHAR(500), 
	enabled BOOLEAN NOT NULL, 
	lease_token VARCHAR(64), 
	lease_until DATETIME, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_connection_owner_role UNIQUE (installation_id, owner_type, owner_id, role), 
	FOREIGN KEY(installation_id) REFERENCES plugin_installations (id), 
	FOREIGN KEY(secret_id) REFERENCES plugin_secrets (id)
);
CREATE TABLE plugin_permissions (
	id INTEGER NOT NULL, 
	installation_id INTEGER NOT NULL, 
	permission VARCHAR(200) NOT NULL, 
	scope VARCHAR(200) NOT NULL, 
	approved_by INTEGER NOT NULL, 
	approved_at DATETIME NOT NULL, 
	revoked_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_permission_install_scope UNIQUE (installation_id, permission, scope), 
	FOREIGN KEY(installation_id) REFERENCES plugin_installations (id), 
	FOREIGN KEY(approved_by) REFERENCES readers (id)
);
CREATE TABLE podcast_access_logs (
	id INTEGER NOT NULL, 
	subscription_id INTEGER NOT NULL, 
	book_id INTEGER, 
	edition_id INTEGER, 
	chapter_id INTEGER, 
	kind VARCHAR(32) NOT NULL, 
	method VARCHAR(12), 
	status INTEGER, 
	range_start BIGINT, 
	range_end BIGINT, 
	bytes_sent BIGINT, 
	ip VARCHAR(128), 
	user_agent VARCHAR(1000), 
	protected BOOLEAN, 
	create_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(subscription_id) REFERENCES podcast_subscriptions (id)
);
CREATE TABLE audiobook_bookmarks (
	id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	edition_id INTEGER NOT NULL, 
	chapter_id INTEGER NOT NULL, 
	position_ms BIGINT, 
	segment_id VARCHAR(64), 
	note VARCHAR(1000), 
	create_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id), 
	FOREIGN KEY(edition_id) REFERENCES audiobook_editions (id), 
	FOREIGN KEY(chapter_id) REFERENCES audiobook_chapters (id)
);
CREATE TABLE audiobook_progress (
	id INTEGER NOT NULL, 
	reader_id INTEGER NOT NULL, 
	edition_id INTEGER NOT NULL, 
	chapter_id INTEGER, 
	position_ms BIGINT, 
	segment_id VARCHAR(64), 
	listened_ms BIGINT, 
	is_finished BOOLEAN, 
	version INTEGER, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_audiobook_progress_reader_edition UNIQUE (reader_id, edition_id), 
	FOREIGN KEY(reader_id) REFERENCES readers (id), 
	FOREIGN KEY(edition_id) REFERENCES audiobook_editions (id), 
	FOREIGN KEY(chapter_id) REFERENCES audiobook_chapters (id)
);
CREATE TABLE plugin_entity_matches (
	id INTEGER NOT NULL, 
	connection_id INTEGER NOT NULL, 
	source_type VARCHAR(64) NOT NULL, 
	external_id VARCHAR(500) NOT NULL, 
	book_id INTEGER NOT NULL, 
	method VARCHAR(32) NOT NULL, 
	confidence FLOAT NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	confirmed_by INTEGER, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_entity_match_source UNIQUE (connection_id, source_type, external_id), 
	FOREIGN KEY(connection_id) REFERENCES plugin_connections (id), 
	FOREIGN KEY(confirmed_by) REFERENCES readers (id)
);
CREATE TABLE plugin_runs (
	id INTEGER NOT NULL, 
	connection_id INTEGER NOT NULL, 
	parent_run_id INTEGER, 
	action VARCHAR(32) NOT NULL, 
	"trigger" VARCHAR(32) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	requested_by INTEGER NOT NULL, 
	counts TEXT, 
	cursor_before TEXT, 
	cursor_after TEXT, 
	input_data TEXT, 
	error_code VARCHAR(128), 
	error_message VARCHAR(1000), 
	attempt INTEGER NOT NULL, 
	duration_ms BIGINT NOT NULL, 
	create_time DATETIME NOT NULL, 
	started_at DATETIME, 
	finished_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(connection_id) REFERENCES plugin_connections (id), 
	FOREIGN KEY(parent_run_id) REFERENCES plugin_runs (id), 
	FOREIGN KEY(requested_by) REFERENCES readers (id)
);
CREATE TABLE plugin_run_items (
	id INTEGER NOT NULL, 
	run_id INTEGER NOT NULL, 
	external_id VARCHAR(500) NOT NULL, 
	entity_type VARCHAR(64) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	operation VARCHAR(32), 
	error_code VARCHAR(128), 
	error_message VARCHAR(1000), 
	payload_hash VARCHAR(64), 
	data TEXT, 
	create_time DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_run_item_external UNIQUE (run_id, external_id), 
	FOREIGN KEY(run_id) REFERENCES plugin_runs (id)
);
CREATE TABLE plugin_source_records (
	id INTEGER NOT NULL, 
	connection_id INTEGER NOT NULL, 
	source VARCHAR(200) NOT NULL, 
	external_id VARCHAR(500) NOT NULL, 
	entity_type VARCHAR(64) NOT NULL, 
	entity_id VARCHAR(500), 
	run_id INTEGER NOT NULL, 
	raw_hash VARCHAR(64) NOT NULL, 
	remote_updated_at DATETIME, 
	local_modified BOOLEAN NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	data TEXT, 
	create_time DATETIME NOT NULL, 
	update_time DATETIME NOT NULL, 
	rolled_back_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_plugin_source_record_identity UNIQUE (connection_id, entity_type, external_id), 
	FOREIGN KEY(connection_id) REFERENCES plugin_connections (id), 
	FOREIGN KEY(run_id) REFERENCES plugin_runs (id)
);
